tape( 'the function preserves the reference evaluation order when scaling (upper triangle)', function test( t ) {
	var expectedAP;
	var equed;
	var AP;
	var S;

	AP = new Float64Array( roundingU.AP );
	S = new Float64Array( roundingU.S );

	expectedAP = new Float64Array( roundingU.AP_out );

	// Note: every entry of this fixture distinguishes the LAPACK evaluation order `AP*(CJ*S(I))` from `(CJ*AP)*S(I)`, which differ by one ULP...
	equed = ndarray( 'column-major', 'upper', roundingU.N, AP, roundingU.strideAP, roundingU.offsetAP, S, roundingU.strideS, roundingU.offsetS, roundingU.scond, roundingU.amax );
	t.strictEqual( equed, roundingU.equed_out, 'returns expected value' );
	t.strictEqual( isSameFloat64Array( AP, expectedAP ), true, 'returns expected value' );
	t.end();
});

